// Shim local mínimo de `ws` (RFC 6455, só frames de texto) para rodar
// o servidor em dev no sandbox. NÃO usar em produção.
import { EventEmitter } from "node:events";
import crypto from "node:crypto";

const GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

class WebSocket extends EventEmitter {
  constructor(socket) {
    super();
    this.socket = socket;
    this.readyState = 1; // OPEN
    this._buf = Buffer.alloc(0);
    socket.on("data", (d) => this._onData(d));
    socket.on("close", () => this._die());
    socket.on("error", () => this._die());
  }
  get OPEN() {
    return 1;
  }
  _die() {
    if (this.readyState === 3) return;
    this.readyState = 3;
    this.emit("close");
  }
  _onData(chunk) {
    this._buf = Buffer.concat([this._buf, chunk]);
    for (;;) {
      const f = this._decode();
      if (!f) break;
      if (f.opcode === 0x8) {
        try {
          this.socket.end();
        } catch {}
        this._die();
        return;
      } else if (f.opcode === 0x9) {
        this._frame(0xa, f.payload); // pong
      } else if (f.opcode === 0xa) {
        this.emit("pong");
      } else {
        this.emit("message", f.payload); // text/binary
      }
    }
  }
  _decode() {
    const b = this._buf;
    if (b.length < 2) return null;
    const opcode = b[0] & 0x0f;
    const masked = (b[1] & 0x80) !== 0;
    let len = b[1] & 0x7f;
    let off = 2;
    if (len === 126) {
      if (b.length < off + 2) return null;
      len = b.readUInt16BE(off);
      off += 2;
    } else if (len === 127) {
      if (b.length < off + 8) return null;
      len = Number(b.readBigUInt64BE(off));
      off += 8;
    }
    let mask;
    if (masked) {
      if (b.length < off + 4) return null;
      mask = b.subarray(off, off + 4);
      off += 4;
    }
    if (b.length < off + len) return null;
    let payload = b.subarray(off, off + len);
    if (masked) {
      const out = Buffer.allocUnsafe(len);
      for (let i = 0; i < len; i++) out[i] = payload[i] ^ mask[i & 3];
      payload = out;
    }
    this._buf = b.subarray(off + len);
    return { opcode, payload };
  }
  _frame(opcode, data) {
    if (this.readyState !== 1) return;
    const payload = Buffer.isBuffer(data) ? data : Buffer.from(String(data));
    const len = payload.length;
    let header;
    if (len < 126) {
      header = Buffer.from([0x80 | opcode, len]);
    } else if (len < 65536) {
      header = Buffer.alloc(4);
      header[0] = 0x80 | opcode;
      header[1] = 126;
      header.writeUInt16BE(len, 2);
    } else {
      header = Buffer.alloc(10);
      header[0] = 0x80 | opcode;
      header[1] = 127;
      header.writeBigUInt64BE(BigInt(len), 2);
    }
    try {
      this.socket.write(Buffer.concat([header, payload]));
    } catch {}
  }
  send(data) {
    this._frame(0x1, data);
  }
  ping() {
    this._frame(0x9, Buffer.alloc(0));
  }
  terminate() {
    try {
      this.socket.destroy();
    } catch {}
    this._die();
  }
  close() {
    this._frame(0x8, Buffer.alloc(0));
    try {
      this.socket.end();
    } catch {}
  }
}

class WebSocketServer extends EventEmitter {
  constructor({ server }) {
    super();
    this.clients = new Set();
    server.on("upgrade", (req, socket) => this._accept(req, socket));
  }
  _accept(req, socket) {
    const key = req.headers["sec-websocket-key"];
    if (!key) {
      socket.destroy();
      return;
    }
    const accept = crypto
      .createHash("sha1")
      .update(key + GUID)
      .digest("base64");
    socket.write(
      "HTTP/1.1 101 Switching Protocols\r\n" +
        "Upgrade: websocket\r\n" +
        "Connection: Upgrade\r\n" +
        "Sec-WebSocket-Accept: " +
        accept +
        "\r\n\r\n",
    );
    const ws = new WebSocket(socket);
    this.clients.add(ws);
    ws.on("close", () => this.clients.delete(ws));
    this.emit("connection", ws, req);
  }
}

export { WebSocketServer, WebSocket };
export default { WebSocketServer, WebSocket };
